import{_ as o,C as i,o as g,c as u,j as n,a as h,E as e}from"./chunks/framework.CRKgIIuH.js";const m=JSON.parse('{"title":"Quiz tổng hợp — Workflow (10 câu, làm sau 6 bài)","description":"","frontmatter":{"quizKey":"final-quiz","questions":[{"id":"Q1.","text":"Sắp xếp đúng thứ tự workflow: (a) Chuẩn hóa, (b) Thiết kế & DMP, (c) Kết thúc/lưu trữ, (d) Thu thập, (e) FAIR & chia sẻ.","options":[{"key":"A","text":"b → d → a → e → c."},{"key":"B","text":"d → b → a → c → e."},{"key":"C","text":"b → a → d → e → c."},{"key":"D","text":"a → b → d → e → c."}],"answer":"A","explain":""},{"id":"Q2.","text":"Một nghiên cứu không viết DMP, thu thập xong mới nghĩ đến việc chia sẻ dữ liệu. Hậu quả nào có khả năng xảy ra nhất?","options":[{"key":"A","text":"Chỉ mất thêm 1 ngày."},{"key":"B","text":"Thiếu metadata, biến không thống nhất, không xin được phê duyệt chia sẻ — phải làm lại phần lớn công việc quản trị."},{"key":"C","text":"Không có hậu quả gì."},{"key":"D","text":"Dữ liệu tự động trở nên FAIR."}],"answer":"B","explain":""},{"id":"Q3.","text":"Bệnh viện A dùng FHIR để gửi dữ liệu cho bệnh viện B, rồi cả hai cùng phân tích trên OMOP CDM. Nhận định nào đúng?","options":[{"key":"A","text":"Phải chuyển sang CDISC trước."},{"key":"B","text":"Dùng thừa chuẩn, chỉ cần một."},{"key":"C","text":"Đúng vai trò: FHIR để trao đổi, OMOP để phân tích."},{"key":"D","text":"FHIR và OMOP không thể dùng chung."}],"answer":"C","explain":""},{"id":"Q4.","text":"Dữ liệu khuyết vì bệnh nhân nặng không lấy được mẫu xét nghiệm. Cách xử lý đúng nhất là gì?","options":[{"key":"A","text":"Xóa toàn bộ bệnh nhân đó."},{"key":"B","text":"Bỏ qua, không ghi lại."},{"key":"C","text":"Điền giá trị trung bình cho tất cả."},{"key":"D","text":"Nhận diện đây có thể là MNAR, ghi lại giả định, dùng phương pháp phù hợp và phân tích độ nhạy."}],"answer":"D","explain":""},{"id":"Q5.","text":"Theo Thông tư 13/2025/TT-BYT, hạn triển khai bệnh án điện tử của bệnh viện là khi nào?","options":[{"key":"A","text":"30/09/2025."},{"key":"B","text":"31/12/2026."},{"key":"C","text":"01/01/2027."},{"key":"D","text":"Không có hạn."}],"answer":"A","explain":"Hạn 31/12/2026 áp cho các cơ sở khác, không phải bệnh viện."},{"id":"Q6.","text":"Một dataset đạt k-anonymity với k=5. Điều này đảm bảo điều gì?","options":[{"key":"A","text":"Dữ liệu đã được mã hóa."},{"key":"B","text":"Mỗi tổ hợp quasi-identifier xuất hiện ít nhất 5 lần, nên không thể phân biệt một cá nhân chỉ bằng liên kết trực tiếp — nhưng vẫn có thể bị tấn công bằng thông tin nền hoặc thiếu đa dạng giá trị nhạy cảm."},{"key":"C","text":"Không ai có thể tái định danh bằng bất kỳ cách nào."},{"key":"D","text":"Dữ liệu được phép công khai."}],"answer":"B","explain":""},{"id":"Q7.","text":"Muốn dữ liệu dùng được cho AI, ngoài sạch, còn cần gì nhất?","options":[{"key":"A","text":"Định dạng Excel."},{"key":"B","text":"Chỉ cần nhiều biến."},{"key":"C","text":"Nguồn gốc rõ ràng (provenance), mô tả đặc tính, và quản trị đạo đức/pháp lý — theo 7 tiêu chí của Bridge2AI (preprint chưa bình duyệt)."},{"key":"D","text":"Dung lượng lớn."}],"answer":"C","explain":""},{"id":"Q8.","text":"Nghiên cứu kết thúc, nhóm xóa file dữ liệu bằng cách xóa thông thường trong hệ điều hành. Đủ chưa?","options":[{"key":"A","text":"Chỉ cần khi dữ liệu lớn."},{"key":"B","text":"Không cần hủy, cứ giữ mãi."},{"key":"C","text":"Đủ."},{"key":"D","text":"Chưa — cần hủy an toàn theo chuẩn như NIST SP 800-88, và ghi lại việc hủy."}],"answer":"D","explain":""},{"id":"Q9.","text":"Vì sao bước 1 dựa trên đánh giá FAIR ban đầu và bước 7 đánh giá lại sau triển khai?","options":[{"key":"A","text":"Vì chỉ cần đánh giá ở hai thời điểm đó, các bước giữa không cần theo dõi."},{"key":"B","text":"Vì đánh giá FAIR chỉ nhằm quyết định có công khai toàn bộ dữ liệu hay không."},{"key":"C","text":"Vì đánh giá ban đầu giúp xác định khoảng cách cần cải thiện, còn đánh giá sau triển khai kiểm tra kết quả và mức trưởng thành đạt được."},{"key":"D","text":"Vì bước 7 thay thế cho việc lập kế hoạch ở bước 1."}],"answer":"C","explain":""},{"id":"Q10.","text":"Một học viên nói: “Dữ liệu của tôi đã FAIR nên tôi công khai toàn bộ lên mạng.” Sai ở đâu?","options":[{"key":"A","text":"Không sai."},{"key":"B","text":"FAIR không có nghĩa là mở hết; dữ liệu sức khỏe thường FAIR nhưng truy cập có kiểm soát."},{"key":"C","text":"FAIR chỉ áp dụng cho dữ liệu mở."},{"key":"D","text":"Phải công khai mới gọi là FAIR."}],"answer":"B","explain":""}],"lessonAnswers":{"module-1-dmp":["A","B","C","D"],"module-2-collection":["A","B","C","D"],"module-3-standards":["A","B","C","D"],"module-4-quality":["A","B","C","D"],"module-5-fair":["A","D","C","D"],"module-6-privacy-ai":["A","B","C","D"]}},"headers":[],"relativePath":"course/final-quiz.md","filePath":"course/final-quiz.md"}'),l={name:"course/final-quiz.md"};function k(r,t,s,p,x,d){const c=i("Quiz"),a=i("QuizResult");return g(),u("div",null,[t[0]||(t[0]=n("h1",{id:"quiz-tong-hop-—-workflow-10-cau-lam-sau-6-bai",tabindex:"-1"},[h("Quiz tổng hợp — Workflow (10 câu, làm sau 6 bài) "),n("a",{class:"header-anchor",href:"#quiz-tong-hop-—-workflow-10-cau-lam-sau-6-bai","aria-label":'Permalink to "Quiz tổng hợp — Workflow (10 câu, làm sau 6 bài)"'},"​")],-1)),e(c),e(a),t[1]||(t[1]=n("p",null,[n("strong",null,"Cách tính điểm:"),h(" mỗi câu 1 điểm, tổng 34 câu (24 câu theo bài + 10 câu tổng hợp). Đạt khi ≥ 24/34 "),n("strong",null,"và đúng ít nhất 2/3 câu Q1–Q3"),h(" của quiz tổng hợp. Học viên nên làm quiz tổng hợp tối đa 2 lần như hướng dẫn tự học; site tĩnh không cưỡng chế giới hạn này.")],-1))])}const b=o(l,[["render",k]]);export{m as __pageData,b as default};
